css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .3); position: relative; }
.loader span { position: absolute; top: 50%; left: 0; width: calc(var(--loader-size) * .24); height: calc(var(--loader-size) * .24); margin-top: calc(var(--loader-size) * -.12); border-radius: 50%; background: linear-gradient(90deg, var(--accent), var(--accent-2)); animation: elastic calc(var(--loader-speed) * 1.4) cubic-bezier(.5, -0.3, .5, 1.3) infinite; }
@keyframes elastic { 0% { left: 0; transform: scaleX(1); } 30% { transform: scaleX(1.7) scaleY(.72); } 50% { left: calc(100% - var(--loader-size) * .24); transform: scaleX(1); } 80% { transform: scaleX(1.7) scaleY(.72); } 100% { left: 0; transform: scaleX(1); } }
